<?php require __DIR__.'/../includes/bootstrap.php';require_admin();if(!academy_ready())redirect('upgrade-multiverse-academy.php');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$status=$_POST['status']??'pending';if(in_array($status,['draft','pending','approved','rejected','archived'],true)){db()->prepare('UPDATE academy_courses SET status=?,is_featured=? WHERE id=?')->execute([$status,isset($_POST['is_featured'])?1:0,$id]);flash('success','Course updated.');}redirect('admin/academy.php');}$courses=db()->query('SELECT c.*,u.display_name owner_name,(SELECT COUNT(*) FROM academy_enrollments e WHERE e.course_id=c.id) students FROM academy_courses c JOIN users u ON u.id=c.owner_user_id ORDER BY FIELD(c.status,"pending","approved","draft","rejected","archived"),c.created_at DESC')->fetchAll();app_header('Academy Admin');?><section class="dashboard-hero"><p class="eyebrow">ADMINISTRATION</p><h1>Multiverse Academy</h1><p>Approve, feature, and manage courses.</p></section><section class="app-card"><div class="table-wrap"><table><thead><tr><th>Course</th><th>Owner</th><th>Students</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($courses as $c):?><tr><td><a href="../academy/manage.php?id=<?=(int)$c['id']?>"><?=e($c['title'])?></a></td><td><?=e($c['owner_name'])?></td><td><?=(int)$c['students']?></td><td><?=e(ucfirst($c['status']))?></td><td><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$c['id']?>"><select name="status"><?php foreach(['draft','pending','approved','rejected','archived'] as $status):?><option value="<?=$status?>" <?=$c['status']===$status?'selected':''?>><?=e(ucfirst($status))?></option><?php endforeach?></select><label class="check-row"><input type="checkbox" name="is_featured" <?=$c['is_featured']?'checked':''?>> Featured</label><button class="button primary small">Save</button></form></td></tr><?php endforeach?></tbody></table></div></section><?php app_footer();
